package net.farmingtales.ftboss.boss.ai;

import java.util.*;
import org.objectweb.asm.Opcodes;
import org.objectweb.asm.tree.*;

public final class NativeQingyiRollStartInstaller implements Opcodes {
    private static final String ROOT="net/farmingtales/ftboss/",BOSS=ROOT+"entity/EasterBossEntity",LEVEL="net/minecraft/server/level/ServerLevel",LIVING="net/minecraft/world/entity/LivingEntity";
    private static final String DESC="(L"+LEVEL+";L"+LIVING+";)V";
    private static final Map<String,String> PREIMAGES=Map.of("skillQingyi","218cfd8065b625bc887d153242e5122c6ab3e981a70b3f4c7b6acfb52f317f5b","skillXueliRoll","8da4d699bbcd323b65afcd913cf1a9458d6050535bdf3516f1123196d8edd213");
    private NativeQingyiRollStartInstaller(){}
    private static void require(boolean value,String reason){if(!value)throw new IllegalStateException(reason);}
    private static MethodNode method(ClassNode owner,String name){require(owner.name.equals(BOSS),"Exact native Boss owner required");List<MethodNode> methods=owner.methods.stream().filter(value->value.name.equals(name)&&value.desc.equals(DESC)).toList();require(methods.size()==1,"Exact single native Qingyi/roll start required");return methods.getFirst();}
    private static List<AbstractInsnNode> code(Iterable<AbstractInsnNode> instructions){List<AbstractInsnNode> result=new ArrayList<>();for(AbstractInsnNode instruction:instructions)if(instruction.getOpcode()>=0)result.add(instruction);return result;}
    private static MethodInsnNode one(MethodNode method,String owner,String name,String descriptor){List<MethodInsnNode> calls=new ArrayList<>();for(AbstractInsnNode instruction:method.instructions)if(instruction instanceof MethodInsnNode member&&member.owner.equals(owner)&&member.name.equals(name)&&member.desc.equals(descriptor))calls.add(member);require(calls.size()==1,"Exact Qingyi/roll start call inventory: "+owner+"."+name);return calls.getFirst();}
    private static AbstractInsnNode previous(AbstractInsnNode instruction){AbstractInsnNode result=instruction.getPrevious();while(result!=null&&result.getOpcode()<0)result=result.getPrevious();return result;}
    private static boolean equal(AbstractInsnNode left,AbstractInsnNode right){if(left==null||left.getOpcode()!=right.getOpcode())return false;if(left instanceof VarInsnNode value&&right instanceof VarInsnNode wanted)return value.var==wanted.var;if(left instanceof LdcInsnNode value&&right instanceof LdcInsnNode wanted)return Objects.equals(value.cst,wanted.cst);if(left instanceof FieldInsnNode value&&right instanceof FieldInsnNode wanted)return value.owner.equals(wanted.owner)&&value.name.equals(wanted.name)&&value.desc.equals(wanted.desc);if(left instanceof MethodInsnNode value&&right instanceof MethodInsnNode wanted)return value.owner.equals(wanted.owner)&&value.name.equals(wanted.name)&&value.desc.equals(wanted.desc)&&value.itf==wanted.itf;return left instanceof InsnNode&&right instanceof InsnNode;}
    private static InsnList nativeRoll(){InsnList result=new InsnList();result.add(new VarInsnNode(ALOAD,0));result.add(new LdcInsnNode("roll_cast"));result.add(new LdcInsnNode("hold"));result.add(new LdcInsnNode(30));result.add(new MethodInsnNode(INVOKESTATIC,ROOT+"xueli_cast_actions/CastServer","nativeAction","(L"+BOSS+";Ljava/lang/String;Ljava/lang/String;I)V",false));return result;}
    private static InsnList qingyiDash(){InsnList result=new InsnList();result.add(new VarInsnNode(ALOAD,0));result.add(new VarInsnNode(ALOAD,0));result.add(new FieldInsnNode(GETFIELD,BOSS,"riptideDir","Lnet/minecraft/world/phys/Vec3;"));result.add(new VarInsnNode(ALOAD,0));result.add(new FieldInsnNode(GETFIELD,BOSS,"riptideTicks","I"));result.add(new MethodInsnNode(INVOKESTATIC,ROOT+"qingyilight/LightHooks","dash","(L"+BOSS+";Lnet/minecraft/world/phys/Vec3;I)V",false));return result;}
    private static void removeThrough(MethodNode method,AbstractInsnNode last,InsnList expected){List<AbstractInsnNode> wanted=code(expected);List<AbstractInsnNode> removed=new ArrayList<>();AbstractInsnNode cursor=last;for(int index=wanted.size()-1;index>=0;index--){require(equal(cursor,wanted.get(index)),"Exact original Qingyi/roll hook operands/ordering differ");removed.add(cursor);cursor=previous(cursor);}for(AbstractInsnNode instruction:removed)method.instructions.remove(instruction);}
    public static void install(ClassNode owner){for(String name:new TreeSet<>(PREIMAGES.keySet())){MethodNode method=method(owner,name);if(!NativeBossLivingComposerSupportV2.methodFingerprint(method).equals(PREIMAGES.get(name))){verify(method);continue;}if(name.equals("skillQingyi")){List<AbstractInsnNode> anchors=code(method.instructions).stream().filter(value->value instanceof FieldInsnNode member&&member.getOpcode()==PUTFIELD&&member.owner.equals(BOSS)&&member.name.equals("riptideTicks")&&member.desc.equals("I")).toList();require(anchors.size()==1,"Exact one native riptide tick initialization anchor");method.instructions.insert(anchors.getFirst(),qingyiDash());}else{List<AbstractInsnNode> returns=code(method.instructions).stream().filter(value->value.getOpcode()==RETURN).toList();require(returns.size()==1,"Exact native roll single terminal return");method.instructions.insertBefore(returns.getFirst(),nativeRoll());}method.maxStack=Math.max(method.maxStack,4);verify(method);}}
    private static void verify(MethodNode source){MethodNode restored=NativeBossLivingComposerSupportV2.copy(source);if(source.name.equals("skillQingyi"))removeThrough(restored,one(restored,ROOT+"qingyilight/LightHooks","dash","(L"+BOSS+";Lnet/minecraft/world/phys/Vec3;I)V"),qingyiDash());else removeThrough(restored,one(restored,ROOT+"xueli_cast_actions/CastServer","nativeAction","(L"+BOSS+";Ljava/lang/String;Ljava/lang/String;I)V"),nativeRoll());require(NativeBossLivingComposerSupportV2.methodFingerprint(restored).equals(PREIMAGES.get(source.name)),"Whole frozen native start changed outside exact original callback addition: "+source.name);}
    public static void verifyInstalled(ClassNode owner){for(String name:PREIMAGES.keySet())verify(method(owner,name));}
}
